const root=document.querySelector('#root');
const state={page:'Overview',data:{},mobile:false,ai:[],me:null};
const icon={Overview:'◫',Inventory:'▦',Warehouses:'⌂',Products:'◇',Orders:'▤',Receiving:'⇩',Transfers:'⇄',Customers:'♙',Suppliers:'♧',Reports:'▤',Audit:'◷',Settings:'⚙'};
const nav=[['Workspace','Overview','Inventory','Warehouses','Products','Orders','Shipments'],['Operations','Receiving','Purchasing','Stock counts','Transfers','Returns'],['Manage','Customers','Suppliers','Expenses','Storage billing','Invoices','Payables','Profitability','Reports','Audit','Team & roles','Settings']];
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const res=await fetch('/api/v1'+path,{credentials:'same-origin',headers:{'content-type':'application/json',...(options.headers||{})},...options});const json=await res.json();if(!res.ok)throw new Error(json.error?.message||'Request failed');return json.data}
function money(n){return 'PKR '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:0})}
function shell(){return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">⌂</div><span>stockpilot</span><button class="icon-btn mobile-close" data-action="menu">×</button></div><button class="company-switch"><span class="company-avatar">A</span><span class="company-copy"><b>Atlas Trading Co.</b><small>Karachi, Pakistan</small></span><span>⌄</span></button><div class="nav-scroll">${nav.map(([section,...items])=>`<section class="nav-section"><div class="nav-label">${section}</div>${items.map(x=>`<button class="nav-item ${state.page===x?'active':''}" data-page="${x}"><span class="nav-symbol">${icon[x]||'•'}</span><span>${x}</span></button>`).join('')}</section>`).join('')}</div><div class="sidebar-bottom"><button class="help-link">? &nbsp; Help & support</button><div class="profile"><div class="profile-avatar">AK</div><div class="profile-copy"><b>Ahmed Khan</b><small>Business owner</small></div><button class="logout-btn" data-action="logout">↪</button></div></div></aside><main class="main-area"><header class="topbar"><button class="icon-btn menu-toggle" data-action="menu">☰</button><div class="breadcrumb">Workspace <span>/</span> <b>${escapeHtml(state.page)}</b></div><div class="top-actions"><button class="search-control" data-page="Products">⌕ <span>Search products...</span><kbd>⌘ K</kbd></button><button class="icon-btn" data-action="refresh">⟳</button><div class="today-label">${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</div></div></header><div class="content-wrap" id="content"><div class="loading-state">Loading workspace…</div></div></main></div><div id="overlay"></div>`}
function login(){root.innerHTML=`<div class="login-page"><form class="login-card" id="loginForm"><div class="brand"><div class="brand-mark">⌂</div><span>stockpilot</span></div><h1>Welcome back</h1><p>Sign in to your warehouse workspace.</p><label>Email<input name="email" type="email" required value="owner@example.com" autocomplete="username"></label><label>Password<input name="password" type="password" required value="StockpilotDemo2026!" autocomplete="current-password"></label><button class="btn btn-primary" type="submit">Sign in <span>→</span></button><small>Development demo account: owner@example.com · StockpilotDemo2026!</small><div class="form-error" id="loginError"></div></form></div>`;document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))});await start()}catch(err){document.querySelector('#loginError').textContent=err.message}}}
async function start(){try{state.me=await api('/auth/me');root.innerHTML=shell();root.querySelector('.company-copy b').textContent=state.me.tenant.name;root.querySelector('.profile-copy b').textContent=state.me.user.name;root.querySelector('.profile-copy small').textContent=state.me.role;await loadPage()}catch{login()}}
function kpi(label,value,note,color='teal'){return `<article class="kpi-card"><div class="kpi-top"><span>${label}</span><i class="kpi-icon ${color}">${({teal:'▦',blue:'↗',amber:'▤',violet:'⌂'})[color]}</i></div><div class="kpi-value">${value}</div><div class="kpi-foot"><b>${note}</b></div></article>`}
function section(title,sub,right=''){return `<div class="section-head"><div><h2>${title}</h2><span class="muted">${sub}</span></div>${right}</div>`}
async function loadPage(){const box=document.querySelector('#content');if(!box)return;try{if(state.page==='Overview'){const d=await api('/dashboard');state.data.dashboard=d;box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">BUSINESS COMMAND CENTER <span class="live-dot"></span> LIVE</div><h1>Good morning, Ahmed <span>☀️</span></h1><p>Here’s what’s happening across your business today.</p></div><div class="welcome-actions"><button class="btn btn-secondary" data-action="refresh">↻ Refresh</button><button class="btn btn-primary" data-action="quick">＋ New transaction</button></div></div><div class="intelligence"><div class="ai-icon">✦</div><div class="intel-copy"><div class="intel-title">Today’s intelligence <span class="ai-tag">DATA GROUNDED</span></div><p>${Number(d.alerts.lowStock)} products are at or below reorder point. Your available stock is <b>${Number(d.inventory.units).toLocaleString()} units</b> across ${d.inventory.skus} SKUs. Ask a question to explore the numbers.</p></div><button class="ask-button" data-action="ask">Ask Stockpilot →</button></div>${section('Business snapshot','Live inventory and warehouse operations')}<section class="kpi-grid">${kpi('Inventory value',money(d.inventory.value),`${Number(d.inventory.units).toLocaleString()} units`)}${kpi('Active products',d.inventory.skus,`${d.inventory.low} low on stock`,'blue')}${kpi('Open orders',d.openOrders,'Awaiting dispatch','amber')}${kpi('Warehouse capacity',`${d.warehouses.length?Math.round(d.warehouses.reduce((a,w)=>a+(w.capacity?100*w.used/w.capacity:0),0)/d.warehouses.length):0}%`,`${d.warehouses.length} locations`,'violet')}</section><section class="middle-grid"><div class="panel chart-panel"><div class="panel-heading"><div><h3>Warehouse utilization</h3><span class="muted">Stock quantity vs. configured space capacity</span></div></div>${d.warehouses.map(w=>`<div class="warehouse-meter"><div><b>${escapeHtml(w.name)}</b><span>${Number(w.used).toLocaleString()} / ${Number(w.capacity).toLocaleString()} units</span></div><div class="meter"><i style="width:${Math.min(100,w.capacity?100*w.used/w.capacity:0)}%"></i></div></div>`).join('')}<p class="muted">Set location capacity to make these utilization figures meaningful.</p></div><div class="panel alerts-panel"><div class="panel-heading"><div><h3>Needs your attention</h3><span class="muted">Prioritized for you</span></div></div>${d.alerts.lowStock?`<div class="alert-row"><i class="alert-dot red"></i><div><b>Stock at reorder point</b><small>${d.alerts.lowStock} products need review</small></div><button data-page="Inventory">Review →</button></div>`:`<div class="empty-mini">No urgent stock alerts.</div>`}<div class="alert-row"><i class="alert-dot orange"></i><div><b>${d.openOrders} open orders</b><small>Review reserved orders and dispatch</small></div><button data-page="Orders">View →</button></div></div></section><section class="panel tasks-panel"><div class="panel-heading"><div><h3>Quick actions</h3><span class="muted">Keep work moving</span></div></div><div class="quick-grid"><button data-action="receive">＋ Receive goods</button><button data-action="product">＋ Add product</button><button data-action="order">＋ Create sales order</button><button data-action="transfer">⇄ Transfer stock</button></div></section><footer>Stockpilot · Warehouse command center <span class="footer-right">● API connected · data updated ${new Date(d.generatedAt).toLocaleTimeString()}</span></footer>`;return}
 const endpoint={Inventory:'/inventory',Warehouses:'/warehouses',Products:'/products',Orders:'/orders',Receiving:'/receipts',Transfers:'/transfers',Customers:'/customers',Suppliers:'/suppliers',Audit:'/audit',Reports:'/dashboard'}[state.page];if(state.page==='Reports'){const d=await api(endpoint);box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">ANALYTICS</div><h1>Reports</h1><p>Current inventory and warehouse snapshot</p></div><button class="btn btn-secondary" data-action="csv">↓ Export CSV</button></div>${section('Inventory valuation','Current on-hand value at cost')}<div class="panel report-summary"><b>${money(d.inventory.value)}</b><span>${d.inventory.skus} SKUs · ${Number(d.inventory.units).toLocaleString()} units</span><button class="text-link" data-page="Inventory">View inventory →</button></div>`;return}
 if(state.page==='Settings'){box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">CONFIGURATION</div><h1>Settings</h1><p>Company profile and workspace configuration</p></div></div><div class="panel settings-card"><h3>Atlas Trading Co.</h3><p>PKR · Pakistan · Asia/Karachi</p><p>Demo owner account: owner@example.com</p><p>Session security: HttpOnly cookie · 24-hour session</p></div>`;return}
 const rows=await api(endpoint);state.data[state.page]=rows;box.innerHTML=renderTable(state.page,rows);
 }catch(e){box.innerHTML=`<div class="panel error-panel"><b>Couldn’t load ${escapeHtml(state.page)}</b><p>${escapeHtml(e.message)}</p><button class="btn btn-secondary" data-action="refresh">Try again</button></div>`}}
function renderTable(page,rows){let title=page;let action=({Products:['product','＋ Add product'],Warehouses:['warehouse','＋ Add warehouse'],Inventory:['adjust','± Adjust stock'],Orders:['order','＋ Sales order'],Receiving:['receive','＋ Receive goods'],Transfers:['transfer','⇄ Transfer stock'],Customers:['customer','＋ Add customer'],Suppliers:['supplier','＋ Add supplier']})[page];let body='';if(page==='Products')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.sku)}</b></td><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.category)}</td><td>${money(x.cost)}</td><td>${money(x.price)}</td><td>${x.reorder}</td></tr>`).join('');else if(page==='Inventory')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.product?.sku)}</b></td><td>${escapeHtml(x.product?.name)}</td><td>${escapeHtml(x.warehouse?.name)}</td><td>${escapeHtml(x.location?.code)}</td><td>${x.qty}</td><td>${escapeHtml(x.status)}</td><td>${x.qty<=x.product?.reorder?'<span class="status-pill warning">Reorder</span>':'<span class="status-pill">Healthy</span>'}</td></tr>`).join('');else if(page==='Warehouses')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.code)}</b></td><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.city)}</td><td>${Number(x.capacity).toLocaleString()}</td><td>${escapeHtml(x.status||'active')}</td></tr>`).join('');else if(page==='Orders')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.id.slice(0,8))}</b></td><td>${escapeHtml(x.customer)}</td><td>${escapeHtml(x.warehouse)}</td><td>${money(x.total)}</td><td><span class="status-pill">${escapeHtml(x.status)}</span></td><td>${x.status==='dispatched'?'Done':`<button class="table-action" data-dispatch="${x.id}">Dispatch</button>`}</td></tr>`).join('');else if(page==='Receiving')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.id.slice(0,8))}</b></td><td>${escapeHtml(x.warehouse_id.slice(0,8))}</td><td>${escapeHtml(x.status)}</td><td>${new Date(x.created_at+'Z').toLocaleString()}</td></tr>`).join('');else if(page==='Transfers')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.id.slice(0,8))}</b></td><td>${escapeHtml(x.product_id.slice(0,8))}</td><td>${x.qty}</td><td>${escapeHtml(x.status)}</td><td>${new Date(x.created_at+'Z').toLocaleString()}</td></tr>`).join('');else if(page==='Customers'||page==='Suppliers')body=rows.map(x=>`<tr><td><b>${escapeHtml(x.name)}</b></td><td>${escapeHtml(x.phone||'—')}</td><td>${escapeHtml(x.email||'—')}</td><td>${x.credit_limit?money(x.credit_limit):'—'}</td></tr>`).join('');else if(page==='Audit')body=rows.map(x=>`<tr><td>${new Date(x.created_at+'Z').toLocaleString()}</td><td><b>${escapeHtml(x.action)}</b></td><td>${escapeHtml(x.entity)}</td><td>${escapeHtml(x.entity_id.slice(0,12))}</td><td>${escapeHtml(x.actor.slice(0,10))}</td></tr>`).join('');let headers=({Products:['SKU','Product','Category','Cost','Price','Reorder'],Inventory:['SKU','Product','Warehouse','Location','Available','Status','Alert'],Warehouses:['Code','Warehouse','City','Capacity','Status'],Orders:['Order','Customer','Warehouse','Total','Status','Action'],Receiving:['GRN','Warehouse ID','Status','Received'],Transfers:['Transfer','Product ID','Qty','Status','Created'],Customers:['Customer','Phone','Email','Credit limit'],Suppliers:['Supplier','Phone','Email','—'],Audit:['Timestamp','Action','Entity','Entity ID','Actor']})[page]||[];return `<div class="welcome-row"><div><div class="eyebrow">WORKSPACE · ${page.toUpperCase()}</div><h1>${page}</h1><p>${rows.length} records · Tenant-scoped live data</p></div>${action?`<button class="btn btn-primary" data-action="${action[0]}">${action[1]}</button>`:''}</div><div class="table-toolbar"><input id="tableSearch" placeholder="Search ${page.toLowerCase()}…"/><button class="btn btn-secondary" data-action="csv">↓ CSV</button></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="empty-row">No ${page.toLowerCase()} yet. Add your first record to get started.</td></tr>`}</tbody></table></div></div>`}
function modal(title,fields,submit,label='Save'){document.querySelector('#overlay').innerHTML=`<div class="modal-scrim" data-close="true"><form class="ask-modal data-modal" id="dataForm"><div class="modal-head"><div class="ai-icon">＋</div><div><b>${title}</b><small>Changes are recorded in the company audit trail</small></div><button type="button" class="icon-btn" data-close="true">×</button></div><div class="modal-fields">${fields}</div><div class="form-error" id="formError"></div><button class="btn btn-primary" type="submit">${label}</button></form></div>`;document.querySelector('#dataForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{await submit(data);document.querySelector('#overlay').innerHTML='';await loadPage()}catch(err){document.querySelector('#formError').textContent=err.message}}}
const field=(label,name,type='text',required=true,placeholder='')=>`<label>${label}<input name="${name}" type="${type}" ${required?'required':''} placeholder="${placeholder}"></label>`;
async function action(name){try{if(name==='menu'){document.querySelector('#sidebar').classList.toggle('sidebar-open');return}if(name==='refresh')return loadPage();if(name==='logout'){await api('/auth/logout',{method:'POST',body:'{}'});return login()}if(name==='quick'){document.querySelector('#overlay').innerHTML=`<div class="modal-scrim" data-close="true"><div class="ask-modal quick-modal"><div class="modal-head"><b>New transaction</b><button class="icon-btn" data-close="true">×</button></div>${[['receive','Receive goods'],['product','Add product'],['order','Create sales order'],['transfer','Transfer stock'],['adjust','Adjust inventory']].map(([x,l])=>`<button class="quick-option" data-action="${x}">${l} →</button>`).join('')}</div></div>`;return}if(name==='product')return modal('Add product',field('SKU','sku')+field('Product name','name')+field('Category','category', 'text',false,'General')+field('Barcode','barcode','text',false)+field('Unit cost (PKR)','cost','number')+field('Selling price (PKR)','price','number')+field('Reorder level','reorder','number'),d=>api('/products',{method:'POST',body:JSON.stringify(d)}));if(name==='warehouse')return modal('Add warehouse',field('Code','code')+field('Warehouse name','name')+field('City','city')+field('Capacity (units)','capacity','number'),d=>api('/warehouses',{method:'POST',body:JSON.stringify(d)}));if(name==='customer')return modal('Add customer',field('Customer name','name')+field('Phone','phone','tel')+field('Email','email','email',false)+field('Credit limit (PKR)','creditLimit','number',false),d=>api('/customers',{method:'POST',body:JSON.stringify(d)}));if(name==='supplier')return modal('Add supplier',field('Supplier name','name')+field('Phone','phone','tel',false)+field('Email','email','email',false),d=>api('/suppliers',{method:'POST',body:JSON.stringify(d)}));if(name==='receive'||name==='adjust')return receiveModal(name);if(name==='order')return orderModal();if(name==='transfer')return transferModal();if(name==='ask')return askModal();if(name==='csv')return exportCsv();}catch(e){alert(e.message)}}
async function options(endpoint,label){const rows=await api(endpoint);return rows.map(x=>`<option value="${x.id}">${escapeHtml(x.name||x.sku||x.code)}</option>`).join('')}
async function receiveModal(adjust=false){const [products,warehouses,locations]=await Promise.all([api('/products'),api('/warehouses'),api('/locations')]);const p=products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join(''),w=warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join(''),l=locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)} · ${escapeHtml(x.name)}</option>`).join('');modal(adjust?'Adjust stock':'Receive goods',`<label>Warehouse<select name="warehouseId" required>${w}</select></label><label>Product<select name="productId" required>${p}</select></label><label>Location<select name="locationId" required>${l}</select></label>${field(adjust?'Quantity change (+/-)':'Quantity received','qty','number')}${field('Batch / lot (optional)','lot','text',false)}${adjust?field('Reason','reason'):''}`,async d=>{if(adjust)return api('/adjustments',{method:'POST',body:JSON.stringify({warehouseId:d.warehouseId,productId:d.productId,locationId:d.locationId,quantityDelta:Number(d.qty),reason:d.reason})});return api('/receipts',{method:'POST',body:JSON.stringify({warehouseId:d.warehouseId,lines:[{productId:d.productId,locationId:d.locationId,qty:Number(d.qty),lot:d.lot}]})})})}
async function orderModal(){const [products,customers,warehouses]=await Promise.all([api('/products'),api('/customers'),api('/warehouses')]);modal('Create sales order',`<label>Customer<select name="customerId" required>${customers.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Warehouse<select name="warehouseId" required>${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Product<select name="productId" required>${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Quantity','qty','number')}`,d=>api('/orders',{method:'POST',body:JSON.stringify({customerId:d.customerId,warehouseId:d.warehouseId,lines:[{productId:d.productId,qty:Number(d.qty)}]})}) )}
async function transferModal(){const [products,warehouses,locations]=await Promise.all([api('/products'),api('/warehouses'),api('/locations')]);const w=warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join(''),l=locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)}</option>`).join('');modal('Transfer stock',`<label>Product<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label><label>From warehouse<select name="fromWarehouseId">${w}</select></label><label>From location<select name="fromLocationId">${l}</select></label><label>To warehouse<select name="toWarehouseId">${w}</select></label><label>To location<select name="toLocationId">${l}</select></label>${field('Quantity','qty','number')}`,d=>api('/transfers',{method:'POST',body:JSON.stringify({...d,qty:Number(d.qty)})}) )}
function askModal(){document.querySelector('#overlay').innerHTML=`<div class="modal-scrim" data-close="true"><div class="ask-modal"><div class="modal-head"><div class="ai-icon">✦</div><div><b>Ask Stockpilot</b><small>Answers grounded in your live inventory data</small></div><button class="icon-btn" data-close="true">×</button></div><div class="suggestions"><span>Try asking</span><button data-question="How much inventory do I have?">How much inventory do I have?</button><button data-question="Which products are low?">Which products are low?</button><button data-question="Give me today's warehouse summary">Give me today’s summary</button></div><div class="ai-answer" id="aiAnswer"></div><form class="ask-input" id="askForm"><input name="message" placeholder="Ask about your warehouse…" required/><button class="send-btn">→</button></form><div class="modal-foot">✦ Factual quantities come from the tenant database</div></div></div>`;const send=async msg=>{document.querySelector('#aiAnswer').innerHTML='<div class="muted">Looking up your business data…</div>';try{const d=await api('/ai/chat',{method:'POST',body:JSON.stringify({message:msg})});document.querySelector('#aiAnswer').innerHTML=`<b>${escapeHtml(d.answer)}</b>${d.facts.lowStock.length?`<ul>${d.facts.lowStock.map(x=>`<li>${escapeHtml(x.sku)} · ${escapeHtml(x.name)}: ${x.qty} on hand (reorder at ${x.reorder})</li>`).join('')}</ul>`:''}`}catch(e){document.querySelector('#aiAnswer').textContent=e.message}};document.querySelector('#askForm').onsubmit=e=>{e.preventDefault();send(new FormData(e.currentTarget).get('message'))};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>send(b.dataset.question))}
function exportCsv(){const rows=state.data[state.page]||[];if(!rows.length)return alert('There are no rows to export.');const keys=Object.keys(rows[0]),csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`stockpilot-${state.page.toLowerCase()}.csv`;a.click();URL.revokeObjectURL(a.href)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-page],[data-action],[data-close],[data-dispatch]');if(!t)return;if(t.dataset.page){state.page=t.dataset.page;loadPage();root.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page))}if(t.dataset.action)action(t.dataset.action);if(t.dataset.close)document.querySelector('#overlay').innerHTML='';if(t.dataset.dispatch)api(`/orders/${t.dataset.dispatch}/dispatch`,{method:'POST',body:'{}'}).then(loadPage).catch(e=>alert(e.message))});
// Fulfilment advances through explicit server-validated pick, pack, and dispatch states.
document.addEventListener('click',async e=>{const button=e.target.closest('[data-dispatch]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const id=button.dataset.dispatch,order=(state.data.Orders||[]).find(x=>x.id===id);try{if(!order)return;if(order.status==='reserved'){const [balances,products]=await Promise.all([api('/inventory'),api('/products')]);const lines=[];for(const line of order.lines){const product=products.find(p=>p.id===line.product_id),balance=balances.find(b=>b.product_id===line.product_id&&b.status==='reserved'&&Number(b.qty)>=Number(line.qty));if(!product||!balance)throw new Error(`Reserved stock could not be located for ${line.sku}.`);const scannedProduct=prompt(`Scan product barcode or SKU for ${line.sku} · ${line.name}`);if(scannedProduct===null)return;if(scannedProduct.trim()!==(product.barcode||product.sku))throw new Error('Wrong product barcode. Pick stopped.');const scannedLocation=prompt(`Scan pick location for ${line.sku}`,balance.location.code);if(scannedLocation===null)return;if(scannedLocation.trim()!==balance.location.code)throw new Error('Wrong location barcode. Pick stopped.');const quantity=Number(prompt(`Confirm picked quantity for ${line.sku}`,String(line.qty)));if(quantity!==Number(line.qty))throw new Error('Picked quantity must exactly match the reserved order quantity.');lines.push({productId:line.product_id,locationId:balance.location_id,qty:quantity})}await api(`/orders/${id}/pick`,{method:'POST',body:JSON.stringify({lines})})}else if(order.status==='picked'){const packageCount=Number(prompt('Number of packages','1'));if(!Number.isInteger(packageCount)||packageCount<1)return;await api(`/orders/${id}/pack`,{method:'POST',body:JSON.stringify({packageCount})})}else if(order.status==='packed'){await api(`/orders/${id}/dispatch`,{method:'POST',body:'{}'})}await loadPage()}catch(error){alert(error.message)}},true);
new MutationObserver(()=>{for(const b of document.querySelectorAll('[data-dispatch]')){const row=(state.data.Orders||[]).find(x=>x.id===b.dataset.dispatch);if(row)b.textContent=row.status==='reserved'?'Scan & pick':row.status==='picked'?'Pack':row.status==='packed'?'Dispatch':'Done'}}).observe(document.querySelector('#root'),{childList:true,subtree:true});
const originalLoadPage=loadPage;loadPage=async function(){if(state.page!=='Team & roles')return originalLoadPage();const box=document.querySelector('#content');try{const members=await api('/team');state.data[state.page]=members;box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">ACCESS CONTROL</div><h1>Team & roles</h1><p>${members.length} company members · role permissions enforced by the API</p></div><button class="btn btn-primary" data-action="team">＋ Add teammate</button></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${escapeHtml(m.name)}</b></td><td>${escapeHtml(m.email)}</td><td><span class="status-pill">${escapeHtml(m.role)}</span></td></tr>`).join('')}</tbody></table></div></div>`}catch(e){box.innerHTML=`<div class="panel error-panel"><b>Couldn’t load team members</b><p>${escapeHtml(e.message)}</p></div>`}};
