const loginView=login;login=function(){loginView();const card=document.querySelector('.login-card');const signup=document.createElement('button');signup.type='button';signup.className='signup-link';signup.textContent='Set up a new company';card.append(signup);signup.onclick=()=>{const form=document.querySelector('#loginForm');document.querySelector('.login-card h1').textContent='Create your company';document.querySelector('.login-card>p').textContent='Start with a secure owner account.';document.querySelector('.login-card label').insertAdjacentHTML('beforebegin',`<label>Company name<input name="company" required autocomplete="organization"></label><label>Your name<input name="name" required autocomplete="name"></label>`);form.elements.email.value='';form.elements.password.value='';form.elements.password.autocomplete='new-password';form.querySelector('button[type=submit]').innerHTML='Create company <span>→</span>';signup.remove();form.onsubmit=async ev=>{ev.preventDefault();try{await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await start()}catch(err){document.querySelector('#loginError').textContent=err.message}}}};
const extraModules={Purchasing:{endpoint:'/purchase-orders',action:'purchase',label:'＋ Create purchase order',cols:['PO','Supplier','Warehouse','Total','Status'],map:x=>[x.id.slice(0,8),x.supplier_id?.slice(0,8),x.warehouse_id?.slice(0,8),money(x.total),x.status],workflow:'po'},'Stock counts':{endpoint:'/stock-counts',action:'count',label:'＋ Start stock count',cols:['Count','Warehouse','Status','Created'],map:x=>[x.id.slice(0,8),x.warehouse_id.slice(0,8),x.status,x.created_at],workflow:'count'},Returns:{endpoint:'/returns',action:'return',label:'＋ Receive a return',cols:['Return','Order','Reason','Status','Created'],map:x=>[x.id.slice(0,8),x.order_id.slice(0,8),x.reason,x.status,x.created_at]},Expenses:{endpoint:'/expenses',action:'expense',label:'＋ Add expense',cols:['Category','Amount','Warehouse','Date','Memo'],map:x=>[x.category,money(x.amount),x.warehouse_id?.slice(0,8)||'—',x.spent_at,x.memo]},'Storage billing':{endpoint:'/storage-invoices',action:'storageInvoice',label:'＋ Generate invoice',cols:['Invoice','Customer','Period','Units','Amount','Status'],map:x=>[x.id.slice(0,8),x.customer_id.slice(0,8),`${x.period_start} – ${x.period_end}`,x.quantity,money(x.amount),x.status]},Invoices:{endpoint:'/invoices',cols:['Invoice','Customer','Order','Total','Paid','Due','Status'],map:x=>[x.invoice_number,x.customer_id.slice(0,8),x.order_id.slice(0,8),money(x.total),money(x.paid),x.due_at,x.status],workflow:'payment',documentType:'sales_invoice'},Payables:{endpoint:'/supplier-bills',action:'generateBill',label:'＋ Generate bill from received PO',cols:['Bill','Supplier','PO','Total','Paid','Due','Status'],map:x=>[x.bill_number,x.supplier_id.slice(0,8),x.purchase_order_id.slice(0,8),money(x.total),money(x.paid),x.due_at,x.status],workflow:'payment',documentType:'supplier_bill'},Shipments:{endpoint:'/shipments',action:'refresh',label:'↻ Refresh',cols:['Shipment','Order','Carrier','Tracking','Status','Dispatched'],map:x=>[x.id.slice(0,8),x.order_id.slice(0,8),x.carrier||'—',x.tracking_number||'—',x.status,x.dispatched_at],workflow:'shipment'}};
