const previousModuleLoad=loadPage;loadPage=async function(){const cfg=extraModules[state.page];if(!cfg)return previousModuleLoad();const box=document.querySelector('#content');try{const rows=await api(cfg.endpoint);state.data[state.page]=rows;const buttons=state.page==='Storage billing'?`<button class="btn btn-secondary" data-action="storageRate">＋ Set rate</button><button class="btn btn-primary" data-action="storageInvoice">${cfg.label}</button>`:cfg.action?`<button class="btn btn-primary" data-action="${cfg.action}">${cfg.label}</button>`:'';box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">BUSINESS OPERATIONS</div><h1>${state.page}</h1><p>${rows.length} records · Company-scoped data</p></div><div class="welcome-actions">${buttons}</div></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr>${cfg.cols.map(c=>`<th>${c}</th>`).join('')}<th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr>${cfg.map(x).map(v=>`<td>${escapeHtml(v)}</td>`).join('')}<td>${cfg.workflow==='po'?x.status==='draft'?`<button class="table-action" data-po-action="submit" data-id="${x.id}">Submit</button>`:x.status==='submitted'?`<button class="table-action" data-po-action="approve" data-id="${x.id}">Approve</button>`:'—':cfg.workflow==='count'&&x.status==='pending_approval'?`<button class="table-action" data-count-approve="${x.id}">Review & approve</button>`:cfg.workflow==='payment'&&x.status!=='paid'?`<button class="table-action" data-payment-type="${cfg.documentType}" data-id="${x.id}" data-balance="${x.total-x.paid}">Record payment</button>`:'—'}</td></tr>`).join('')||`<tr><td class="empty-row" colspan="${cfg.cols.length+1}">No records yet. Use the action above to get started.</td></tr>`}</tbody></table></div></div>`}catch(e){box.innerHTML=`<div class="panel error-panel"><b>Couldn’t load ${state.page}</b><p>${escapeHtml(e.message)}</p></div>`}};
const actionsBeforeBusiness=action;action=async function(name){if(name==='purchase'){const [products,suppliers,warehouses]=await Promise.all([api('/products'),api('/suppliers'),api('/warehouses')]);return modal('Create purchase order',`<label>Supplier<select name="supplierId">${suppliers.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Warehouse<select name="warehouseId">${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Product<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Quantity','qty','number')}${field('Unit cost (PKR)','cost','number')}${field('Expected date','expectedAt','date',false)}`,d=>api('/purchase-orders',{method:'POST',body:JSON.stringify({supplierId:d.supplierId,warehouseId:d.warehouseId,expectedAt:d.expectedAt,lines:[{productId:d.productId,qty:Number(d.qty),cost:Number(d.cost)}]})}))}if(name==='count'){const [products,warehouses,locations]=await Promise.all([api('/products'),api('/warehouses'),api('/locations')]);return modal('Start stock count',`<label>Warehouse<select name="warehouseId">${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Product<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Location<select name="locationId">${locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)}</option>`).join('')}</select></label>${field('Physical quantity counted','counted','number')}`,d=>api('/stock-counts',{method:'POST',body:JSON.stringify({warehouseId:d.warehouseId,lines:[{productId:d.productId,locationId:d.locationId,counted:Number(d.counted)}]})}))}if(name==='expense'){const warehouses=await api('/warehouses');return modal('Record warehouse expense',field('Category','category')+field('Amount (PKR)','amount','number')+`<label>Warehouse<select name="warehouseId"><option value="">Company-wide</option>${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Date','spentAt','date')}${field('Memo','memo','text',false)}`,d=>api('/expenses',{method:'POST',body:JSON.stringify({...d,amount:Number(d.amount)})}))}if(name==='storageRate'){const customers=await api('/customers');return modal('Set customer storage rate',`<label>Customer<select name="customerId">${customers.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('PKR per stored unit per day','rate','number')}`,d=>api('/storage-rates',{method:'POST',body:JSON.stringify({...d,rate:Number(d.rate),currency:'PKR'})}))}if(name==='storageInvoice'){const customers=await api('/customers'),today=new Date().toISOString().slice(0,10);return modal('Generate storage invoice',`<label>Customer<select name="customerId">${customers.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Period start','periodStart','date')}${field('Period end', 'periodEnd','date')}`,d=>api('/storage-invoices/generate',{method:'POST',body:JSON.stringify(d)}))}if(name==='return'){const [orders,products,locations]=await Promise.all([api('/orders'),api('/products'),api('/locations')]),sent=orders.filter(x=>x.status==='dispatched');return modal('Receive customer return',`<label>Dispatched order<select name="orderId">${sent.map(x=>`<option value="${x.id}">${x.id.slice(0,8)} · ${escapeHtml(x.customer)}</option>`).join('')}</select></label><label>Product<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Putaway location<select name="locationId">${locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)}</option>`).join('')}</select></label>${field('Returned quantity','qty','number')}${field('Reason','reason')+`<label>Disposition<select name="disposition"><option value="quarantine">Quarantine</option><option value="available">Available</option><option value="damaged">Damaged</option></select></label>`}`,d=>api('/returns',{method:'POST',body:JSON.stringify({orderId:d.orderId,reason:d.reason,lines:[{productId:d.productId,locationId:d.locationId,qty:Number(d.qty),disposition:d.disposition}]})}))}return actionsBeforeBusiness(name)};
