// Keep the order list actionable through the same guarded pick → pack → dispatch flow as the API.
const orderActionLabels={reserved:'Pick & verify',picked:'Pack order',packed:'Dispatch',dispatched:'Done'};
const orderActionObserver=new MutationObserver(()=>{
 if(state.page!=='Orders')return;
 const rows=state.data.Orders||[];
 document.querySelectorAll('#content [data-dispatch]').forEach((button,index)=>{
  const order=rows[index],label=orderActionLabels[order?.status]||'Continue';
  if(button.textContent!==label)button.textContent=label;
  if(order?.status==='dispatched')button.disabled=true;
 });
});
orderActionObserver.observe(root,{childList:true,subtree:true});
