const loadPageBeforeOps=loadPage;
loadPage=async function(){
 const box=document.querySelector('#content');
 if(state.page==='Alerts'){
  try{const alerts=await api('/alerts');state.data.Alerts=alerts;box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">OPERATIONS · ALERT CENTER</div><h1>Needs your attention</h1><p>${alerts.length} open items from live company data</p></div><button class="btn btn-secondary" data-action="refresh">↻ Refresh</button></div><div class="alert-list">${alerts.map(a=>`<article class="panel alert-row"><i class="alert-dot ${a.severity==='critical'?'red':'orange'}"></i><div><b>${escapeHtml(a.title)}</b><small>${escapeHtml(a.detail)}</small></div><button class="text-link" data-page="${escapeHtml(a.action.slice(1))}">Review →</button></article>`).join('')||'<div class="panel empty-row">No open alerts. Your inventory and operations are in good shape.</div>'}</div>`}catch(error){box.innerHTML=`<div class="panel error-panel"><b>Couldn’t load alerts</b><p>${escapeHtml(error.message)}</p></div>`}return;
 }
 if(state.page==='Putaway'){
  try{const [products,warehouses,locations]=await Promise.all([api('/products'),api('/warehouses'),api('/locations')]);const wh=warehouses[0]?.id||'',prod=products[0]?.id||'';box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">OPERATIONS · STORAGE</div><h1>Putaway</h1><p>Find a suitable bin using existing product placement and configured free capacity.</p></div></div><form class="panel modal-fields" id="putawayForm"><label>Warehouse<select name="warehouseId">${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Product<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label><button class="btn btn-primary">Suggest a location</button><div id="putawayResult" class="report-summary"></div></form><div class="panel table-panel"><div class="panel-heading"><h3>Warehouse locations</h3></div><div class="table-scroll"><table><thead><tr><th>Code</th><th>Location</th><th>Type</th><th>Capacity</th><th>Barcode</th></tr></thead><tbody>${locations.map(x=>`<tr><td><b>${escapeHtml(x.code)}</b></td><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.kind)}</td><td>${Number(x.capacity).toLocaleString()}</td><td>${escapeHtml(x.barcode||x.code)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">Create a warehouse location to begin putaway.</td></tr>'}</tbody></table></div></div>`;const form=document.querySelector('#putawayForm');form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));try{const result=await api(`/putaway/suggest?warehouseId=${encodeURIComponent(values.warehouseId)}&productId=${encodeURIComponent(values.productId)}`);const el=document.querySelector('#putawayResult');el.innerHTML=result.location?`<b>Recommended bin: ${escapeHtml(result.location.code)} · ${escapeHtml(result.location.name)}</b><span>${escapeHtml(result.reason)} ${Number(result.location.used).toLocaleString()} / ${Number(result.location.capacity||0).toLocaleString()} units</span>`:`<b>No suitable bin found</b><span>${escapeHtml(result.reason)}</span>`}catch(error){document.querySelector('#putawayResult').textContent=error.message}};if(wh&&prod)form.requestSubmit()}catch(error){box.innerHTML=`<div class="panel error-panel"><b>Couldn’t load putaway</b><p>${escapeHtml(error.message)}</p></div>`}return;
 }
 return loadPageBeforeOps();
};
function openGlobalSearch(){
 const overlay=document.querySelector('#overlay');
 if(!overlay)return;
 overlay.innerHTML=`<div class="modal-scrim" data-close="true"><div class="ask-modal" role="dialog" aria-modal="true" aria-label="Search your workspace"><div class="modal-head"><div><b>Search your workspace</b><small>Products, locations, customers, suppliers, orders and shipments</small></div><button class="icon-btn" data-close="true">×</button></div><input id="globalSearchInput" autocomplete="off" placeholder="Type at least 2 characters…"/><div id="globalSearchResults" class="search-results"><div class="empty-row">Start typing to search company records.</div></div></div></div>`;
 const input=document.querySelector('#globalSearchInput'),results=document.querySelector('#globalSearchResults');let timer;
 input.focus();input.oninput=()=>{clearTimeout(timer);const term=input.value.trim();if(term.length<2){results.innerHTML='<div class="empty-row">Type at least 2 characters.</div>';return}timer=setTimeout(async()=>{results.innerHTML='<div class="muted">Searching…</div>';try{const found=await api(`/search?q=${encodeURIComponent(term)}`);results.innerHTML=found.map(item=>`<button class="search-result" data-search-page="${escapeHtml(item.href.slice(1))}"><span><b>${escapeHtml(item.code||item.label||item.name||item.tracking_number)}</b><small>${escapeHtml(item.type)}${item.name&&item.code?` · ${escapeHtml(item.name)}`:''}</small></span><span>Open →</span></button>`).join('')||'<div class="empty-row">No matching company records.</div>'}catch(error){results.textContent=error.message}},180)};
}
document.addEventListener('click',event=>{if(event.target.closest('.search-control')){event.preventDefault();event.stopImmediatePropagation();openGlobalSearch();return}const result=event.target.closest('[data-search-page]');if(result){event.preventDefault();event.stopImmediatePropagation();state.page=result.dataset.searchPage;document.querySelector('#overlay').innerHTML='';loadPage();root.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item.dataset.page===state.page))}},true);
