const loadFinanceReport=loadPage;loadPage=async function(){if(state.page!=='Profitability')return loadFinanceReport();const box=document.querySelector('#content');try{const d=await api('/reports/profitability');box.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">FINANCE · MANAGEMENT REPORT</div><h1>Profitability</h1><p>Revenue and operating costs from posted warehouse activity · ${d.period.from} to ${d.period.to}</p></div><button class="btn btn-secondary" data-action="refresh">↻ Refresh</button></div><section class="kpi-grid">${kpi('Dispatched revenue',money(d.revenue),'Sales invoices')}${kpi('Cost of goods',money(d.costOfGoods),'Dispatched quantities','amber')}${kpi('Gross profit',money(d.grossProfit),'Revenue less product cost','blue')}${kpi('Operating profit',money(d.estimatedOperatingProfit),'After recorded expenses','violet')}</section><section class="kpi-grid">${kpi('Accounts receivable',money(d.accountsReceivable),'Unpaid sales invoices')}${kpi('Accounts payable',money(d.accountsPayable),'Unpaid supplier bills')}</section><p class="muted">Estimated operating profit excludes taxes, payroll, and costs not entered in the system. Currency: ${escapeHtml(d.currency)}.</p>`}catch(error){box.innerHTML=`<div class="panel error-panel"><b>Couldn’t load profitability</b><p>${escapeHtml(error.message)}</p></div>`}};
const actionBeforeTransferFlow=action;
action=async function(name){if(name==='transfer'){const [products,warehouses,locations]=await Promise.all([api('/products'),api('/warehouses'),api('/locations')]);return modal('Request stock transfer',`<label>Product<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label><label>From warehouse<select name="fromWarehouseId">${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>From location<select name="fromLocationId">${locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label><label>To warehouse<select name="toWarehouseId">${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>To location<select name="toLocationId">${locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Quantity','qty','number')}${field('Notes','notes','text',false)}`,values=>api('/transfers/request',{method:'POST',body:JSON.stringify({...values,qty:Number(values.qty)})}),'Submit transfer request')}return actionBeforeTransferFlow(name)};
const actionBeforeReceivingScan=action;
action=async function(name){if(name==='receive'){const [products,warehouses,locations]=await Promise.all([api('/products'),api('/warehouses'),api('/locations')]);return modal('Receive and scan goods',`<label>Warehouse<select name="warehouseId">${warehouses.map(x=>`<option value="${x.id}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>Product record<select name="productId">${products.map(x=>`<option value="${x.id}">${escapeHtml(x.sku)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Scan product SKU or barcode','scannedProduct','text')}${field('Quantity','qty','number')}<label>Putaway bin<select name="locationId">${locations.map(x=>`<option value="${x.id}">${escapeHtml(x.code)} · ${escapeHtml(x.name)}</option>`).join('')}</select></label>${field('Scan bin code or barcode','scannedLocation','text')}${field('Batch / lot (optional)','lot','text',false)}${field('Expiry date (optional)','expiryDate','date',false)}`,values=>{const product=products.find(x=>x.id===values.productId),location=locations.find(x=>x.id===values.locationId);if(!product||![product.sku,product.barcode].filter(Boolean).includes(String(values.scannedProduct).trim()))throw new Error('Scanned product does not match the selected SKU.');if(!location||![location.code,location.barcode].filter(Boolean).includes(String(values.scannedLocation).trim()))throw new Error('Scanned barcode does not match the selected bin.');return api('/receipts',{method:'POST',body:JSON.stringify({warehouseId:values.warehouseId,lines:[{productId:product.id,locationId:location.id,qty:Number(values.qty),lot:values.lot,expiryDate:values.expiryDate}]})})},'Confirm receipt')}return actionBeforeReceivingScan(name)};
const transferObserver=new MutationObserver(()=>{if(state.page!=='Transfers')return;const rows=state.data.Transfers||[];document.querySelectorAll('#content tbody tr').forEach((row,index)=>{const transfer=rows[index];if(!transfer)return;const next={requested:['approve','Approve'],approved:['pick','Pick'],in_transit:['receive','Receive'],completed:null}[transfer.status],cell=row.lastElementChild;if(!cell)return;if(!next){cell.textContent='Complete';return}const button=`<button class="table-action" data-transfer-id="${transfer.id}" data-transfer-step="${next[0]}">${next[1]}</button>`;if(cell.innerHTML!==button)cell.innerHTML=button})});transferObserver.observe(root,{childList:true,subtree:true});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-transfer-id]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();try{await api(`/transfers/${button.dataset.transferId}/${button.dataset.transferStep}`,{method:'POST',body:'{}'});await loadPage()}catch(error){alert(error.message)}},true);
const lotTableObserver=new MutationObserver(()=>{if(state.page!=='Lots & expiry')return;const rows=state.data[state.page]||[];document.querySelectorAll('#content tbody tr').forEach((row,index)=>{const lot=rows[index],cell=row.lastElementChild;if(!lot||!cell)return;if(lot.expiry_date&&lot.expiry_date<=new Date().toISOString().slice(0,10)&&Number(lot.on_hand)>0)cell.innerHTML=`<button class="table-action" data-expire-lot="${lot.id}">Move to expired</button>`})});lotTableObserver.observe(root,{childList:true,subtree:true});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-expire-lot]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();if(!confirm('Move available quantities of this lot into expired stock?'))return;try{await api('/lots/'+button.dataset.expireLot+'/expire',{method:'POST',body:'{}'});await loadPage()}catch(error){alert(error.message)}},true);